insert into public.products (id, title, slug, price, discount_price, images, category, subcategory, brand, description, specifications, stock, rating, reviews_count, is_featured, is_new, is_bestseller, created_at) values ('p-001', 'Laptomo S6 — 15.6" Гурвалсан дэлгэц', 'laptomo-s6-15-6-triple', 1290000, 1150000, '["https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=1100&q=80","https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=1100&q=80","https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&w=1100&q=80"]', 'triple', 'triple-156', 'Laptomo', 'Laptomo S6 — лаптопыг хормын зуур гурван дэлгэцтэй ажлын станц болгох flagship өргөтгөгч. 15.6" FHD IPS хос дэлгэц, нэг USB-C кабелиар plug & play холбогдоно. 13-17" лаптоптой нийцнэ.', '[{"label":"Дэлгэцийн хэмжээ","value":"15.6\" × 2"},{"label":"Нягтрал","value":"1920 × 1080 (FHD)"},{"label":"Панель","value":"IPS, 16:9"},{"label":"Холболт","value":"USB-C (Full-Featured) / HDMI"},{"label":"Нийцэх лаптоп","value":"13\" – 17\""},{"label":"Эргэлт","value":"180° нугалах"},{"label":"Жин","value":"1.6 кг"}]', 14, 4.9, 42, true, true, true, '2025-05-28T09:00:00Z') on conflict (id) do nothing;
